299	    /**
300	     * The US dollars one unit of the invoice's currency is worth on the date: the latest dated rate on
301	     * or before it, otherwise the standing rate (at par when none is set, or when there is no date).
302	     */
303	    private BigDecimal usdPerOn(LocalDate on) {
304	        if (currency() == Currency.USD) {
305	            return BigDecimal.ONE;
306	        }
307	        BigDecimal rate = usdPer == null ? BigDecimal.ONE : new BigDecimal(usdPer.trim());
308	        if (datedRates == null || on == null) {
309	            return rate;
310	        }
311	        for (String entry : datedRates.split(",")) {
312	            String[] parts = entry.split("=");
313	            if (LocalDate.parse(parts[0].trim()).isAfter(on)) {
314	                break;
315	            }
316	            rate = new BigDecimal(parts[1].trim());
317	        }
318	        return rate;
319	    }
