329	    /** Whether what is left is worth less than {@link #WRITE_OFF_LIMIT} US dollars at the rate on the date. */
330	    private boolean isSmallEnoughToWriteOff(BigDecimal left, LocalDate on) {
331	        return left.multiply(usdPerOn(on)).compareTo(WRITE_OFF_LIMIT) < 0;
332	    }
