334	    /**
335	     * The exchange difference in US dollars of an amount applied to the invoice and paid on the date:
336	     * its dollar value at the rate on the date less its dollar value at the rate on the issue date, each
337	     * rounded half up to the cent (a loss is negative). Nothing for a dollar invoice.
338	     */
339	    public BigDecimal fxDifference(BigDecimal applied, LocalDate paidOn) {
340	        BigDecimal paid = applied.multiply(usdPerOn(paidOn)).setScale(2, RoundingMode.HALF_UP);
341	        BigDecimal issued = applied.multiply(usdPerOn(issueDate)).setScale(2, RoundingMode.HALF_UP);
342	        return paid.subtract(issued);
343	    }
