345	    /**
346	     * The exchange difference in US dollars of every payment (not reversed) applied to the invoice
347	     * (see {@link #fxDifference(BigDecimal, LocalDate)}), added up.
348	     */
349	    public BigDecimal fxDifference(List<Payment> payments) {
350	        return payments.stream().filter(p -> !p.isReversed())
351	                .map(p -> fxDifference(p.amountTo(id), p.getDate()))
352	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
353	    }
