516	    /**
517	     * The retention: the retention percentage of the amount before tax (the subtotal less the
518	     * discount), rounded down to the cent, and never more than the retention cap when there is one.
519	     * Tax is never held back, so the tax rate does not change it.
520	     */
521	    public BigDecimal retention(BigDecimal taxRate) {
522	        if (isCreditNote()) {
523	            return zero();
524	        }
525	        BigDecimal retention = subtotal().subtract(discount()).multiply(retentionPct).divide(BigDecimal.valueOf(100))
526	                .setScale(scale(), RoundingMode.DOWN);
527	        return retentionCap == null ? retention : retention.min(retentionCap.setScale(scale(), RoundingMode.DOWN));
