530	    /**
531	     * The retention still held back at the tax rate: all of it until it is released, less what credit
532	     * notes have cleared of it; then nothing.
533	     */
534	    public BigDecimal retentionHeld(BigDecimal taxRate) {
535	        if (retentionReleasedOn != null) {
536	            return zero();
537	        }
538	        BigDecimal cleared = retentionCredited == null ? BigDecimal.ZERO : retentionCredited;
539	        return retention(taxRate).subtract(cleared).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
540	    }
