542	    /**
543	     * How a credit note of the amount comes off this invoice once the given amount has been paid, at
544	     * the tax rate: first what it still owes, then the retention it holds back. The part taken off in
545	     * all, and of that the part clearing retention; the rest is left over as credit.
546	     */
547	    public BigDecimal[] creditTaken(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
548	        if (hasPlan()) {
549	            // It comes off the plan's instalments to come instead (see #schedule).
550	            return new BigDecimal[] { amount, BigDecimal.ZERO };
551	        }
552	        BigDecimal toDue = amount.min(amountDue(paid, taxRate).max(BigDecimal.ZERO));
553	        BigDecimal toRetention = amount.subtract(toDue).min(retentionHeld(taxRate));
554	        return new BigDecimal[] { toDue.add(toRetention), toRetention };
555	    }
