596	     * The late fee in the invoice's currency: the fee in US dollars converted as a payment in another
597	     * currency is, through the workspace rate on the day it is charged, rounded half up to the
598	     * currency's step.
599	     */
600	    private BigDecimal lateFeeIn(BigDecimal feeUsd, LocalDate on) {
601	        if (currency() == Currency.USD) {
602	            return feeUsd.setScale(scale(), RoundingMode.HALF_UP);
603	        }
604	        return currency().roundToStep(feeUsd.divide(usdPerOn(on), MathContext.DECIMAL128));
