636	                || !today.isAfter(dueDate.plusDays(graceDays()))) {
637	            return;
638	        }
639	        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
640	        BigDecimal fee = lateFeeUsd == null || lateFeeUsd.signum() <= 0 ? zero() : lateFeeIn(lateFeeUsd, dueDate.plusDays(graceDays() + 1));
641	        if (!earnsInterest && fee.signum() <= 0) {
642	            return;
643	        }
