645	        }
646	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
647	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
648	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
649	                .filter(p -> !p.on().isAfter(today))
650	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
651	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
652	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(graceDays())))
653	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
654	        if (owed.subtract(paidInGrace).signum() <= 0) {
655	            return;
656	        }
657	        BigDecimal daily = earnsInterest
658	                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128))
659	                : null;
660	        LocalDate overdueOn = dueDate.plusDays(graceDays() + 1);
661	        BigDecimal charged = BigDecimal.ZERO;
662	        BigDecimal unpaidInterest = BigDecimal.ZERO;
663	        BigDecimal unpaidFee = BigDecimal.ZERO;
664	        boolean feeCharged = false;
665	        LocalDate from = dueDate.plusDays(graceDays());
666	        LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
667	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
668	        BigDecimal feeWaived = BigDecimal.ZERO;
669	        BigDecimal interestWaived = BigDecimal.ZERO;
