672	                if (!feeCharged) {
673	                    unpaidFee = fee;
674	                    feeCharged = true;
675	                }
676	                if (earnsInterest && owed.signum() > 0) {
677	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
678	                    charged = charged.add(earned);
679	                    unpaidInterest = unpaidInterest.add(earned);
680	                }
681	                from = waiveOn;
682	                feeWaived = unpaidFee;
683	                interestWaived = unpaidInterest;
684	                unpaidFee = BigDecimal.ZERO;
685	                unpaidInterest = BigDecimal.ZERO;
686	                waiveOn = null;
687	            }
688	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
689	                unpaidFee = fee;
690	                feeCharged = true;
691	            }
692	            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
693	            unpaidFee = unpaidFee.subtract(toFee);
694	            BigDecimal rest = part.amount().subtract(toFee);
695	            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
696	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
697	                charged = charged.add(earned);
698	                unpaidInterest = unpaidInterest.add(earned);
699	                from = part.on();
700	            }
701	            BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
702	            unpaidInterest = unpaidInterest.subtract(toInterest);
703	            owed = owed.subtract(rest.subtract(toInterest));
704	        }
705	        if (waiveOn != null) {
706	            if (earnsInterest && owed.signum() > 0) {
707	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
708	                charged = charged.add(earned);
709	                unpaidInterest = unpaidInterest.add(earned);
