712	            feeWaived = feeCharged ? unpaidFee : fee;
713	            interestWaived = unpaidInterest;
714	        }
715	        if (earnsInterest && owed.signum() > 0) {
716	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
717	        }
718	        this.lateFee = fee.subtract(feeWaived);
719	        this.lateInterest = charged.subtract(interestWaived);
720	        this.lateWaived = feeWaived.add(interestWaived);
