744	                .forEach(inOrder::add);
745	        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
746	        if (getInterestSaved().signum() > 0 && !inOrder.isEmpty()) {
747	            // The interest dropped by paying the plan off counts as paid with the payment that settled it.
748	            inOrder.add(new Part(inOrder.get(inOrder.size() - 1).on(), Long.MAX_VALUE, getInterestSaved()));
