1378	        BigInteger[] leftovers = new BigInteger[n];
1379	        BigInteger given = BigInteger.ZERO;
1380	        for (int i = 0; i < n; i++) {
1381	            if (subtotalCents.signum() == 0) {
1382	                shares[i] = BigInteger.ZERO;
1383	                leftovers[i] = BigInteger.ZERO;
1384	            } else {
