1431	     * proportion to the lines' exact taxes as the discount is split: each line first gets the whole
1432	     * cents of its exact share (rounded down), then the cents left over go one each to the lines with
1433	     * the largest leftover fractions; between equal fractions the cent goes to the line with the
1434	     * larger exact tax, and between equal exact taxes too to the lower line id. The line taxes add up
1435	     * to the invoice tax.
1436	     */
1437	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
1438	        List<BigDecimal> exact = exactLineTaxes(taxRate);
1439	        int n = lines.size();
1440	        BigInteger taxCents = roundTax(exact).movePointRight(scale()).toBigIntegerExact();
1441	        int common = exact.stream().mapToInt(BigDecimal::scale).max().orElse(0);
1442	        BigInteger[] weights = new BigInteger[n];
1443	        BigInteger total = BigInteger.ZERO;
1444	        for (int i = 0; i < n; i++) {
1445	            weights[i] = exact.get(i).setScale(common).unscaledValue();
1446	            total = total.add(weights[i]);
1447	        }
1448	        if (total.signum() < 0) {
1449	            // Split the magnitude, so the leftover cents are always added, then flip the shares back.
1450	            taxCents = taxCents.negate();
1451	            total = total.negate();
1452	            for (int i = 0; i < n; i++) {
1453	                weights[i] = weights[i].negate();
1454	            }
1455	        }
1456	        BigInteger[] shares = new BigInteger[n];
1457	        BigInteger[] leftovers = new BigInteger[n];
1458	        BigInteger given = BigInteger.ZERO;
1459	        for (int i = 0; i < n; i++) {
1460	            if (total.signum() == 0) {
1461	                shares[i] = BigInteger.ZERO;
1462	                leftovers[i] = BigInteger.ZERO;
1463	            } else {
1464	                // The exact share is tax * exact line tax / total exact tax; all fractions share the
1465	                // total as denominator, so the remainders compare as the fractions do.
1466	                BigInteger[] qr = taxCents.multiply(weights[i]).divideAndRemainder(total);
1467	                if (qr[1].signum() < 0) {
1468	                    qr[0] = qr[0].subtract(BigInteger.ONE);
1469	                    qr[1] = qr[1].add(total);
1470	                }
1471	                shares[i] = qr[0];
1472	                leftovers[i] = qr[1];
1473	            }
1474	            given = given.add(shares[i]);
1475	        }
1476	        List<Integer> order = new ArrayList<>();
1477	        for (int i = 0; i < n; i++) {
1478	            order.add(i);
1479	        }
1480	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
1481	                .thenComparing(Comparator.<Integer, BigInteger>comparing(i -> weights[i]).reversed())
1482	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
1483	        int left = taxCents.subtract(given).intValueExact();
1484	        for (int k = 0; k < left; k++) {
1485	            int i = order.get(k);
1486	            shares[i] = shares[i].add(BigInteger.ONE);
1487	        }
1488	        boolean flipped = exact.stream().reduce(BigDecimal.ZERO, BigDecimal::add).signum() < 0;
1489	        List<BigDecimal> result = new ArrayList<>(n);
1490	        for (BigInteger share : shares) {
