161	                    k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
162	            sums[0] = sums[0].add(due).add(i.retentionHeld(rate));
163	            sums[1] = sums[1].add(i.overdueAmount(paid.get(i.getId()), rate, on));
164	        }
165	        Map<Long, BigDecimal> credits = invoices.credits();
166	        credits.keySet().forEach(clientId -> owed.computeIfAbsent(clientId,
167	                k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) }));
168	        return owed.entrySet().stream().map(e -> {
169	            BigDecimal credit = credits.getOrDefault(e.getKey(), BigDecimal.ZERO).setScale(2);
170	            return new ClientBalance(e.getKey(), e.getValue()[0].subtract(credit).toPlainString(),
171	                    e.getValue()[1].toPlainString(), credit.toPlainString());
172	        }).toList();
173	    }
