337	    /**
338	     * Voids a sent invoice paid nothing but credit used on it when it was sent, and records it in the
339	     * audit; that credit goes back on the client's account, unused again, each payment's part recorded
340	     * in the audit. Empty if no such invoice. A draft, an invoice already void, or one with a payment
341	     * recorded against it is refused.
342	     */
343	    @Transactional
344	    public Optional<Invoice> voidInvoice(Long invoiceId) {
345	        Optional<Invoice> found = load(invoiceId);
346	        found.ifPresent(invoice -> {
347	            if (invoice.isVoid()) {
348	                throw new InvoiceRejectedException("This invoice is already void.");
349	            }
350	            if (invoice.isDraft()) {
351	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
352	            }
353	            if (invoice.isCreditNote()) {
354	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
355	            }
356	            if (invoice.hasCreditNotesIssued()) {
357	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
358	            }
359	            List<Payment> paidBy = payments.findForInvoice(invoice.getId());
360	            if (paidBy.stream().anyMatch(payment -> !payment.onlyCreditUsedOn(invoice.getId()))) {
361	                throw new InvoiceRejectedException("An invoice with a payment recorded against it cannot be voided.");
362	            }
363	            invoice.markVoid();
364	            invoices.saveAndFlush(invoice);
365	            for (Payment payment : paidBy) {
366	                BigDecimal returned = payment.returnCredit(invoice.getId());
367	                payments.saveAndFlush(payment);
368	                audit.record("CREDIT_RETURNED payment=" + payment.getId() + " amount="
369	                        + returned.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
370	            }
371	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
372	        });
373	        return found;
374	    }
