413	    /**
414	     * Records a payment of the amount on the date against a sent invoice that still has something
415	     * due, and records it in the audit; empty if no such invoice. The amount has already been
416	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
417	     * invoice already paid, or a date after today
418	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
419	     * already been checked; one that belongs to a different invoice is refused.
420	     */
421	    @Transactional
422	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
423	            String reference) {
424	        Optional<Invoice> found = load(invoiceId);
425	        found.ifPresent(invoice -> {
426	            if (invoice.isDraft()) {
427	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
428	            }
429	            if (invoice.isVoid()) {
430	                throw new InvoiceRejectedException("A void invoice takes no payments.");
431	            }
432	            if (invoice.isCreditNote()) {
433	                throw new InvoiceRejectedException("A credit note takes no payments.");
434	            }
435	            BigDecimal amount = converted(paidAmount, paidIn, invoice.currency(), date);
436	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
437	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
438	            if (due.signum() <= 0) {
439	                throw new InvoiceRejectedException("This invoice has already been paid.");
440	            }
441	            LocalDate now = today.date();
442	            BigDecimal early = BigDecimal.ZERO;
443	            BigDecimal settle = date.isAfter(now) ? null : invoice.settleAmount(paidSoFar, taxRate.percent(), date);
444	            if (settle != null && amount.compareTo(settle) >= 0) {
445	                early = invoice.earlyDiscount(taxRate.percent());
446	                invoice.takeEarlyDiscount(early);
447	                due = settle;
448	            }
449	            BigDecimal saved = BigDecimal.ZERO;
450	            BigDecimal payoff = date.isAfter(now) ? null : invoice.payoff(paidSoFar, taxRate.percent(), now);
451	            if (payoff != null && amount.compareTo(payoff) >= 0) {
452	                saved = due.subtract(payoff).max(BigDecimal.ZERO);
453	                invoice.saveInterest(saved);
454	                due = payoff;
455	            }
456	            BigDecimal applied = amount.min(due);
457	            if (invoice.hasPlan() && invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
458	                throw new InvoiceRejectedException("A payment must be at least the "
459	                        + invoice.currency().format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
460	                        + " still unpaid on the earliest unpaid instalment, unless it settles the plan.");
461	            }
462	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
463	                throw new InvoiceRejectedException("A part payment must be at least "
464	                        + invoice.currency().format(invoice.minimumPart(taxRate.percent()))
465	                        + " (10% of the total), unless it settles the invoice.");
466	            }
467	            if (date.isAfter(now)) {
468	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
469	            }
470	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
471	                throw new InvoiceRejectedException(
472	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
473	            }
474	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
475	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
476	                        + " is the reference of a different invoice; this invoice's is "
477	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
478	            }
479	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference)
480	                    .paidIn(paidIn, paidAmount, invoice.currency()));
481	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
482	                    + applied.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
483	            if (invoice.currency() != Currency.USD) {
484	                audit.record("FX_DIFFERENCE id=" + invoice.getId() + " payment=" + payment.getId() + " amount="
485	                        + invoice.fxDifference(applied, date).toPlainString());
486	            }
487	            if (early.signum() > 0) {
488	                invoices.saveAndFlush(invoice);
489	                audit.record("EARLY_DISCOUNT id=" + invoice.getId() + " amount=" + early.toPlainString());
490	            }
491	            if (payoff != null && amount.compareTo(payoff) >= 0) {
492	                invoices.saveAndFlush(invoice);
493	                audit.record("PLAN_SETTLED id=" + invoice.getId() + " saved=" + saved.toPlainString());
494	            }
495	            recordWriteOff(invoice);
496	            recordCreditHeld(payment);
497	        });
498	        return found;
499	    }
